package dev.aether.api.security;
import io.jsonwebtoken.Claims;import io.jsonwebtoken.Jwts;import io.jsonwebtoken.io.Decoders;import io.jsonwebtoken.security.Keys;import org.springframework.beans.factory.annotation.Value;import org.springframework.security.core.userdetails.UserDetails;import org.springframework.stereotype.Service;import javax.crypto.SecretKey;import java.time.Instant;import java.util.Date;
@Service public class JwtService { private final SecretKey key; private final long expirationMs; public JwtService(@Value("${security.jwt.secret}") String secret,@Value("${security.jwt.expiration}") long expirationMs){if(secret==null||secret.isBlank())throw new IllegalStateException("JWT_SECRET_BASE64 must be configured with a strong Base64-encoded key (at least 256 bits).");byte[] bytes=Decoders.BASE64.decode(secret);if(bytes.length<32)throw new IllegalStateException("JWT_SECRET_BASE64 must decode to at least 32 bytes.");this.key=Keys.hmacShaKeyFor(bytes);this.expirationMs=expirationMs;} public String issue(UserDetails user){Instant now=Instant.now();return Jwts.builder().subject(user.getUsername()).issuedAt(Date.from(now)).expiration(Date.from(now.plusMillis(expirationMs))).signWith(key).compact();} public String subject(String token){return claims(token).getSubject();} public boolean valid(String token,UserDetails user){Claims claims=claims(token);return user.getUsername().equalsIgnoreCase(claims.getSubject())&&claims.getExpiration().after(new Date());} public long expirationMs(){return expirationMs;} private Claims claims(String token){return Jwts.parser().verifyWith(key).build().parseSignedClaims(token).getPayload();} }
